	}
	return b
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var a, b, c, l int64
	fmt.Fscan(in, &a, &b, &c, &l)

	// sort a,b,c
	if a > b {
		a, b = b, a
	}
	if b > c {
		b, c = c, b
	}
	if a > b {
		a, b = b, a
	}

	var ans int64

	// iterate over possible increase of the largest side
	for x := int64(0); x <= l; x++ {
		C := c + x
		rem := l - x

		// total ways to distribute rem to two sticks: (rem+1)(rem+2)/2
		total := (rem + 1) * (rem + 2) / 2

		// count invalid where C >= A+B
		// A = a + da, B = b + db, da+db <= rem
		// inequality: a + b + da + db <= C  => da+db <= C - a - b
		t := C - a - b
