package main

import (
	"bufio"
	"fmt"
	"os"
)

func min(a, b int64) int64 {
	if a < b {
		return a
	}
	return b
}

func max(a, b int64) int64 {
	if a > b {
		return a
	}
	return b
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var a, b, c, l int64
	fmt.Fscan(in, &a, &b, &c, &l)

	var ans int64 = 0

	// iterate over which stick is the largest after increase
	for t := 0; t < 3; t++ {
		var x, y, z int64
		if t == 0 {
			x, y, z = a, b, c
		} else if t == 1 {
			x, y, z = b, a, c
		} else {
			x, y, z = c, a, b
		}

		// x is the "largest" side after increase
		// we iterate over dx (increase of x)
		for dx := int64(0); dx <= l; dx++ {
			X := x + dx
			rem := l - dx

			// y' = y + dy, z' = z + dz, dy+dz <= rem
			// need triangle inequalities:
			// 1) y' + z' > X
			// 2) y' + X > z'
			// 3) z' + X > y'
			//
			// Since X is intended to be the largest side, we only need:
			// y' + z' > X and y' + z' > X ensures non-degenerate.
			// Other inequalities automatically hold if X is max.

			// dy, dz >= 0, dy+dz <= rem
			// (y+dy) + (z+dz) > X
			// dy + dz > X - y - z
			need := X - y - z + 1 // minimal dy+dz to satisfy strict >
			if need <= 0 {
				need = 0
			}
			if need > rem {
				continue
			}
			// number of (dy,dz) with dy+dz in [need, rem]
			// For fixed s = dy+dz, number of pairs is s+1 (dy from 0..s)
			// sum_{s=need..rem} (s+1) = (rem+1+need)*(rem-need+1)/2
			n := rem - need + 1
			sum := n*(need+rem+1)/2
			ans += sum

			// subtract configurations where X is not actually the largest side:
			// need to ensure y' <= X and z' <= X
			// y+dy <= X => dy <= X - y
			// z+dz <= X => dz <= X - z
			// count pairs violating these and subtract

			// case where y' > X
			if y < X {
				maxDy := rem
				minDy := X - y + 1
				if minDy <= maxDy {
					// dy in [minDy..maxDy], dz in [0..rem-dy]
					// count = sum_{dy=minDy..maxDy} (rem-dy+1)
					// = sum_{k=0..maxDy-minDy} (rem-(minDy+k)+1)
					// = sum_{k=0..n1-1} (rem-minDy+1 - k)
					n1 := maxDy - minDy + 1
					first := rem - minDy + 1
					// arithmetic series: n1*first - n1*(n1-1)/2
					bad := n1*first - n1*(n1-1)/2
					ans -= bad
				}
			} else {
				// y >= X, any positive dy makes y' > X
				if rem > 0 {
					// dy in [1..rem], dz in [0..rem-dy]
					n1 := rem
					first := rem
					bad := n1*first - n1*(n1-1)/2
					ans -= bad
				}
			}

			// case where z' > X
			if z < X {
				maxDz := rem
				minDz := X - z + 1
				if minDz <= maxDz {
					n1 := maxDz - minDz + 1
					first := rem - minDz + 1
					bad := n1*first - n1*(n1-1)/2
					ans -= bad
				}
			} else {
				if rem > 0 {
					n1 := rem
					first := rem
					bad := n1*first - n1*(n1-1)/2
					ans -= bad
				}
			}
		}
	}

	fmt.Println(ans)
}

