func main() {
	in := bufio.NewReader(os.Stdin)
	var a, b, c, l int64
	fmt.Fscan(in, &a, &b, &c, &l)

	// sort a,b,c
	if a > b {
		a, b = b, a
	}
	if b > c {
		b, c = c, b
	}
	if a > b {
		a, b = b, a
	}

	total := (l + 1) * (l + 2) / 2

	// helper to compute invalid count for given base sides x,y,z (sorted) and extra t
	invalid := func(x, y, z, t int64) int64 {
		var res int64 = 0
		// we consider increments dx,dy,dz with dx+dy+dz<=t
		// invalid when x+dx >= y+dy+z+dz  => dx - dy - dz >= y+z-x
		need := y + z - x
		if need <= 0 {
			// even without increments already invalid or degenerate, but we count only configurations
			need = 1
		}
		// iterate dx
		for dx := int64(0); dx <= t; dx++ {
			// inequality: dx - dy - dz >= need
			// with dy+dz = s, s<=t-dx
			// dx - s >= need  => s <= dx-need
			maxS := dx - need
			if maxS < 0 {
				continue
			}
			if maxS > t-dx {
				maxS = t - dx
			}
			if maxS < 0 {
				continue
			}
			res += maxS + 1
		}
		return res
	}

	ans := total
	ans -= invalid(a, b, c, l)
	ans -= invalid(b, c, a, l)
	ans -= invalid(c, a, b, l)

	fmt.Println(ans)
}

