	"os"
)

func max(a, b int64) int64 {
	if a > b {
		return a
	}
	return b
}

func min(a, b int64) int64 {
	if a < b {
		return a
	}
	return b
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var a, b, c, l int64
	fmt.Fscan(in, &a, &b, &c, &l)

	ans := int64(0)

	for i := int64(0); i <= l; i++ {
		x := a + i
		rem := l - i

		// y ranges from b to b+rem, z from c to c+rem, with y+z <= b+c+rem
		// total pairs (y,z) with y,z >= base and y+z <= baseSum+rem
		baseY, baseZ := b, c
		baseSum := baseY + baseZ

		// total pairs without triangle constraint
		// number of (dy,dz) with dy,dz>=0 and dy+dz<=rem is (rem+1)(rem+2)/2
		total := (rem + 1) * (rem + 2) / 2

		// subtract bad pairs where x >= y+z
		// i.e., y+z <= x
		// but also y+z >= baseSum
		// so baseSum <= y+z <= min(x, baseSum+rem)
		upper := min(x, baseSum+rem)
		if upper >= baseSum {
			// number of sums s in [baseSum, upper]
			for s := baseSum; s <= upper; s++ {
				// count pairs (y,z) with y,z>=base and y+z=s
				// y in [base, s-base], z = s-y, must also <= base+rem
				// dy = y-base, dz = z-base => dy+dz = s-baseSum
				// dy in [0, s-baseSum], dz = s-baseSum-dy
				// also dy<=rem, dz<=rem
				t := s - baseSum
				if t < 0 || t > rem*2 {
					continue
				}
				lowDy := int64(0)
				highDy := t
				if highDy > rem {
					highDy = rem
				}
				if t-lowDy > rem {
					lowDy = t - rem
				}
				if highDy >= lowDy {
					bad := highDy - lowDy + 1
					total -= bad
				}
			}
		}

		ans += total
	}

	fmt.Println(ans)
}

