		x := a + i
		rem := l - i

		// y ranges from b to b+rem, z from c to c+rem, with y+z <= b+c+rem
		// total pairs (j,k) with j+k<=rem is (rem+1)(rem+2)/2
		total := (rem + 1) * (rem + 2) / 2

		// subtract invalid where x >= y+z  =>  j+k <= b+c - x - 1
		limit := b + c - x - 1
		if limit >= 0 {
			limit = min(limit, rem)
			invalid := (limit + 1) * (limit + 2) / 2
			total -= invalid
		}

		// subtract invalid where y >= x+z  =>  b+j >= x + c + k +1
		// j - k >= x + c +1 - b
		d := x + c + 1 - b
		if d <= rem {
			// j-k >= d
			// transform to u=j-k, v=k, with j=k+u
			// j,k>=0, j+k<=rem => (k+u)+k<=rem => 2k+u<=rem => k<= (rem-u)/2
			// u ranges from max(d,-rem) to rem
			udMin := max(d, -rem)
			udMax := rem
			if udMin <= udMax {
				invalid2 := int64(0)
				for u := udMin; u <= udMax; u++ {
					maxK := (rem - u) / 2
					if maxK >= 0 {
						invalid2 += maxK + 1
					}
				}
				total -= invalid2
			}
		}

		// subtract invalid where z >= x+y  =>  c+k >= x + b + j +1
		// k - j >= x + b +1 - c
		d2 := x + b + 1 - c
		if d2 <= rem {
			udMin := max(d2, -rem)
			udMax := rem
			if udMin <= udMax {
				invalid3 := int64(0)
				for u := udMin; u <= udMax; u++ {
					maxJ := (rem - u) / 2
					if maxJ >= 0 {
						invalid3 += maxJ + 1
					}
				}
				total -= invalid3
			}
		}

		ans += total
	}

	fmt.Println(ans)
