import (
	"bufio"
	"fmt"
	"os"
)

func max(a, b int64) int64 {
	if a > b {
		return a
	}
	return b
}

func min(a, b int64) int64 {
	if a < b {
		return a
	}
	return b
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var a, b, c, l int64
	fmt.Fscan(in, &a, &b, &c, &l)

	// total number of non-negative integer triples (x,y,z) with x+y+z<=l
	L := l + 2
	total := L * (L + 1) / 2

	ans := total

	// function to subtract invalid configurations for one inequality
	subtract := func(A, B, C int64) {
		// inequality: A + x >= B + y + C + z  -> invalid when A + x <= B + y + C + z
		// rearranged: x - y - z <= B + C - A
		// we consider when A + x <= B + y + C + z, i.e. A + x <= B + C + y + z
		// minimal x that can violate triangle: x0 = B + C - A + 1
		x0 := B + C - A + 1
		if x0 <= 0 {
			return
		}
		if x0 > l {
			return
		}
		// for x in [x0, l], count pairs (y,z) with y+z <= l-x and A+x <= B+C+y+z
		for x := x0; x <= l; x++ {
			rem := l - x
			// need y+z >= A + x - (B + C)
			need := A + x - (B + C)
			if need <= 0 {
				// all pairs with y+z<=rem are invalid
				ans -= (rem + 1) * (rem + 2) / 2
			} else if need <= rem {
				// pairs with sum s from need to rem
				// count = sum_{s=need..rem} (s+1) = (rem+1)(rem+2)/2 - need(need+1)/2
				totalPairs := (rem + 1) * (rem + 2) / 2
				validPairs := need * (need + 1) / 2
				ans -= totalPairs - validPairs
			}
		}
	}

	subtract(a, b, c)
	subtract(b, a, c)
	subtract(c, a, b)

	fmt.Println(ans)
}

