	// where one side >= sum of other two
	countInvalid := func(x, y, z int64) int64 {
		var res int64 = 0
		// we consider x as the potentially largest side
		// increments: dx, dy, dz >= 0, dx+dy+dz <= l
		// condition: x+dx >= y+dy + z+dz  =>  dx - dy - dz >= y+z - x
		need := y + z - x
		// if need <= 0, then even with dx=0, dy=dz=0 we already have invalid,
		// but original sticks are fixed; we still must count all increments
		// satisfying inequality.
		for dx := int64(0); dx <= l; dx++ {
			// dx - dy - dz >= need  =>  dy + dz <= dx - need
			limit := dx - need
			if limit < 0 {
				continue
			}
			if limit > l-dx {
				limit = l - dx
			}
			if limit < 0 {
				continue
			}
			// number of (dy,dz) with dy,dz>=0, dy+dz<=limit is (limit+1)(limit+2)/2
			res += (limit + 1) * (limit + 2) / 2
		}
		return res
	}

	// count invalid for each side being the largest
	ans := total
	ans -= countInvalid(a, b, c)
	ans -= countInvalid(b, a, c)
	ans -= countInvalid(c, a, b)

	fmt.Println(ans)
